CREATE OR REPLACE FUNCTION public.get_credit_transactions() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth AS $$ DECLARE v_user_id uuid := auth.uid(); v_transactions jsonb; BEGIN IF v_user_id IS NULL THEN RAISE EXCEPTION 'Usuário não autenticado'; END IF; SELECT COALESCE(jsonb_agg(to_jsonb(items) ORDER BY items.created_at DESC), '[]'::jsonb) INTO v_transactions FROM (SELECT ct.id, ct.user_id, ct.amount, ct.transaction_type, ct.description, ct.metadata, ct.created_at FROM public.credit_transactions AS ct WHERE ct.user_id = v_user_id ORDER BY ct.created_at DESC LIMIT 20) AS items; RETURN v_transactions; END; $$;